Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    next insert();

    //copy of the salesInvoicetmp from UsingExistingReportData()
    if(this.AVAOrigSalesConfirmHeaderTmp && this.AVAOrigSalesConfirmHeaderTmp != this.RecId)
    {
        AvaReportingMarkupTransTmp::resetIsCopy(this.TableId, this.AVAOrigSalesConfirmHeaderTmp, this.RecId);
    }
    else
    {
        //fill the markuptrans records
        CustConfirmJour custConfirmJour = CustConfirmJour::findRecId(this.JournalRecId);
        if(custConfirmJour)
        {
            boolean proforma = custConfirmJour.isProforma();
            SalesTable salesTable = custConfirmJour.salesTable();

            if(proforma)
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, salesTable, custConfirmJour.LanguageId, proforma, custConfirmJour.Qty, custConfirmJour.SalesBalance, 0.0, salesTable.InclTax);
            }
            else
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, custConfirmJour, custConfirmJour.LanguageId);
            }
        }  
    }

    this.AVAOrigSalesConfirmHeaderTmp = this.RecId;
    this.doUpdate();
}
